import json
n=30
g=[[0]*n for _ in range(n)]
# Existing complete 4x4 panel lattice.
starts=[1,8,15,22]
colors=[[3,2,2,3],[2,8,8,2],[3,2,2,3],[2,8,8,2]]
for bi,rs in enumerate(starts):
  for bj,cs in enumerate(starts):
    v=colors[bi][bj]
    for dr in range(5):
      for dc in range(5):
        g[rs+dr][cs+dc]=4 if dr in (0,4) or dc in (0,4) else v
# Partial fifth panel row and column at bottom/right.
for cs in starts:
  for dc in range(5): g[29][cs+dc]=4
for rs in starts:
  for dr in range(5): g[rs+dr][29]=4
# Connect equal non-dominant marker colors across intervening blank panel gutters.
# 3: horizontal endpoint panels at columns 0 and 3 in panel rows 0 and 2.
for r in [2,3,4,17,18,19]:
  for c in [6,7,13,14,20,21]: g[r][c]=3
# 8: horizontal adjacent endpoints in panel rows 1 and 3.
for r in [9,10,11,23,24,25]:
  for c in [13,14]: g[r][c]=8
# 3 vertical endpoints (panel rows 0 and 2), in panel columns 0 and 3.
for r in [6,7,13,14]:
  for c in [2,3,4,23,24,25]: g[r][c]=3
# 8 vertical endpoints (panel rows 1 and 3), in panel columns 1 and 2.
for r in [13,14,20,21]:
  for c in [9,10,11,16,17,18]: g[r][c]=8
assert len(g)==30 and all(len(row)==30 for row in g)
print(json.dumps(g,separators=(',',':')))

