import json
# Construct exact source grid from the displayed 30x30 test's 4x4 panel pattern.
starts=[1,8,15,22]
vals=[[3,2,2,3],[2,8,8,2],[3,2,2,3],[2,8,8,2]]
g=[[0]*30 for _ in range(30)]
for i,r0 in enumerate(starts):
 for j,c0 in enumerate(starts):
  v=vals[i][j]
  for dr in range(5):
   for dc in range(5):
    g[r0+dr][c0+dc]=4 if dr in (0,4) or dc in (0,4) else v
# Partial fifth panel row and column shown at the lower/right edges.
for c0 in starts:
 for dc in range(5): g[29][c0+dc]=4
for r0 in starts:
 for dr in range(5): g[r0+dr][29]=4
# The far bottom-right partial panel corner is 0 in the provided grid.
# Along each row/column, join occurrences of matching non-background marker colors;
# only recolor intervening 0s, preserving all existing nonzero cells.
for r in range(30):
 for color in (3,8):
  ps=[c for c in range(30) if g[r][c]==color]
  for a,b in zip(ps,ps[1:]):
   for c in range(a+1,b):
    if g[r][c]==0: g[r][c]=color
for c in range(30):
 for color in (3,8):
  ps=[r for r in range(30) if g[r][c]==color]
  for a,b in zip(ps,ps[1:]):
   for r in range(a+1,b):
    if g[r][c]==0: g[r][c]=color
assert len(g)==30 and all(len(row)==30 for row in g)
print(json.dumps(g,separators=(',',':')))

import json
# Source-derived regular lattice panel grid (30x30).
starts=[1,8,15,22]
vals=[[3,2,2,3],[2,8,8,2],[3,2,2,3],[2,8,8,2]]
src=[[0]*30 for _ in range(30)]
for i,r0 in enumerate(starts):
 for j,c0 in enumerate(starts):
  v=vals[i][j]
  for dr in range(5):
   for dc in range(5): src[r0+dr][c0+dc]=4 if dr in (0,4) or dc in (0,4) else v
for c0 in starts:
 for dc in range(5): src[29][c0+dc]=4
for r0 in starts:
 for dr in range(5): src[r0+dr][29]=4
src[29][29]=4
# From the demonstration: connect identical marker colors along a row/column, recoloring only blank gap cells; keep panel contents and borders intact.
out=[row[:] for row in src]
for axis in ('row','col'):
 for color in (3,8):
  lines=range(30)
  for k in lines:
   positions=[]
   for t in range(30):
    r,c=(k,t) if axis=='row' else (t,k)
    if src[r][c]==color: positions.append(t)
   if len(positions)>1:
    for a,b in zip(positions,positions[1:]):
     for t in range(a+1,b):
      r,c=(k,t) if axis=='row' else (t,k)
      if src[r][c]==0: out[r][c]=color
assert len(out)==30 and all(len(row)==30 for row in out)
print(json.dumps(out,separators=(',',':')))

