# Connect aligned instances of each anomalous interior color through zero-valued gaps;
# existing panel content and frame cells remain unchanged.
for r in range(n):
    for color in (3,8):
        cols=[c for c in range(n) if src[r][c]==color]
        if len(cols)>=2:
            for c in range(min(cols),max(cols)+1):
                if src[r][c]==0: out[r][c]=color
for c in range(n):
    for color in (3,8):
        rows=[r for r in range(n) if src[r][c]==color]
        if len(rows)>=2:
            for r in range(min(rows),max(rows)+1):
                if src[r][c]==0: out[r][c]=color
assert len(out)==30 and all(len(row)==30 for row in out)
